#define main legacy_attention_main
#include "../attention-paged-cuda/main.cu"
#undef main
#include <fstream>
#include "study_fixture.h"
std::vector<float>source_uniform(int n,float scale){float*p;GPU_CHECK(cudaMalloc(&p,n*4));uniform_fill_kernel<float><<<(n+255)/256,256>>>(p,n,-scale,scale,1234);GPU_CHECK(cudaGetLastError());std::vector<float>out(n);GPU_CHECK(cudaMemcpy(out.data(),p,n*4,cudaMemcpyDeviceToHost));GPU_CHECK(cudaFree(p));return out;}
int main(){std::vector<double>fixture{3},oracle;FILE*json=fopen("fixture_manifest.json","w");assert(json);fprintf(json,"{\"cases\":[");for(int ci=0;ci<3;ci++){AttentionFixture f(ci);auto q=source_uniform(f.sequences*f.heads*f.head,f.scale),k=source_uniform(f.pages*f.heads*f.head*16,f.kvscale),v=source_uniform(f.pages*f.heads*f.head*16,f.kvscale);float*a;GPU_CHECK(cudaMalloc(&a,f.heads*4));norm_fill_kernel<float><<<1,256>>>(a,f.heads,1234);std::vector<float>alibi(f.heads);GPU_CHECK(cudaMemcpy(alibi.data(),a,f.heads*4,cudaMemcpyDeviceToHost));GPU_CHECK(cudaFree(a));for(double x:{double(f.sequences),double(f.heads),double(f.head),double(f.maxlen),double(f.pages),double(f.style),double(f.scale),double(f.kvscale)})fixture.push_back(x);for(int x:f.lengths)fixture.push_back(x);for(int x:f.tables)fixture.push_back(x);for(auto*arr:{&q,&k,&v,&alibi})for(float x:*arr){assert(std::isfinite(x));fixture.push_back(x);}f.override_inputs(q,k,v,alibi);for(auto*arr:{&q,&k,&v,&alibi})for(float x:*arr){assert(std::isfinite(x));fixture.push_back(x);}auto expected=f.oracle(q,k,v,alibi);for(double x:expected){assert(std::isfinite(x));oracle.push_back(x);}fprintf(json,"%s{\"case\":%d,\"sequences\":%d,\"heads\":%d,\"head_size\":%d,\"max_sequence_length\":%d,\"cache_pages\":%d,\"style\":\"%s\",\"output_values\":%zu}",ci?",":"",ci,f.sequences,f.heads,f.head,f.maxlen,f.pages,ci==0?"originalGPUinitializer":ci==1?"manufacturedpackedlayout_ALiBi_partialpages":"constantV_repeatedpages",q.size());}std::ofstream file("fixture.bin",std::ios::binary);file.write((char*)fixture.data(),fixture.size()*8);std::ofstream gold("oracle.bin",std::ios::binary);gold.write((char*)oracle.data(),oracle.size()*8);fprintf(json,"],\"fixture_count\":%zu,\"oracle_count\":%zu,\"precision\":\"FP32input/compute; independentFloat64densepackedgather/ALiBi/epssoftmax\",\"block_size\":16,\"threads\":128,\"native_GPU_body_unchanged\":true,\"BF16_native_sm70_assertion_recorded\":true,\"atol\":0.00002,\"rtol\":0.00002}\n",fixture.size(),oracle.size());fclose(json);printf("PAGED_FIXTURE %zu ORACLE %zu\n",fixture.size(),oracle.size());}
